#include <iostream>
#include <string>
#include <ncurses.h>

#include "Windows.cpp"
#include "RoomList.cpp"
#include "MessageArea.cpp"
#include "FriendsWindow.cpp"


using namespace std;


int main(){

    //initialize the screen
    initscr();

    Windows ui;
    ui.initialize();

    RoomList topics;
    topics.drawLeft(ui.getTopicsWindow());

    MessageArea generalChat;
    MessageArea sportChat;
    MessageArea musicChat;

    FriendsWindow friends;
    friends.drawWindow(ui.getFriendsWindow());


    string input="";


    //allow keyboard input in the bottom window
    keypad(ui.getChatWindow(),true);

    while (true){

        //we then read the keyboard inputs to do operation with
        int typingInput = wgetch(ui.getChatWindow());

        switch(typingInput){

            case KEY_UP:{

                topics.selectUp();

                    sportChat.textInput("You: "+input);
                    //chat.push_back("You: "+input);
                    sportChat.drawChat(ui.getMainWindow());

                topics.drawLeft(ui.getTopicsWindow());

                break;
            }
            case KEY_DOWN:{

                topics.selectDown();
                topics.drawLeft(ui.getTopicsWindow());

                break;
            }
            // case KEY_LEFT:{
            //     highlight=(highlight == 0)? sideMenu.size() -1: highlight-1;
            //     break;
            // }
            // case KEY_RIGHT:{
            //     highlight=(highlight == sideMenu.size()-1)? 0: highlight+1;
            //     break;
            // }
            case KEY_ENTER:
            case '\n':{

                if(!input.empty()){

                    generalChat.textInput("You: "+input);
                    //chat.push_back("You: "+input);
                    generalChat.drawChat(ui.getMainWindow());

                }

                input.clear();

                wclrtoeol(ui.getChatWindow());

                mvwprintw(ui.getChatWindow(),1,1,"input > ");

                wrefresh(ui.getChatWindow());

                break;
            }
            case KEY_BACKSPACE:
            case 127:
            case '\b': {

                if(!input.empty()){
                    input.pop_back();
                }

                wclrtoeol(ui.getChatWindow());
                wmove(ui.getChatWindow(),1,2);

                mvwprintw(ui.getChatWindow(),1,1,"input > %s", input.c_str());
                wrefresh(ui.getChatWindow());

                break;
            }

        }

        if(typingInput >=32 && typingInput <= 126){

            //cast everything to char to stop display arrow up and down input
            input+=static_cast<char>(typingInput);

            wrefresh(ui.getChatWindow());

            wclrtoeol(ui.getChatWindow());

            wmove(ui.getChatWindow(),1,1);

            mvwprintw(ui.getChatWindow(),1,1,"input > %s",input.c_str());

            wrefresh(ui.getChatWindow());


        }
    }

    endwin();

    return 0;

}

